const seriesTotals = `-- name: SeriesTotals :one
SELECT count(*) AS entered,
    count(*) FILTER (WHERE status IN ('active', 'waiting')) AS active,
    count(*) FILTER (WHERE status = 'finished') AS finished,
    count(*) FILTER (WHERE status = 'exited') AS exited,
    count(*) FILTER (WHERE goal_at IS NOT NULL) AS goal
FROM series_enrollments
WHERE workspace_id = $1 AND series_id = $2 AND NOT test
  AND (end_reason IS NULL OR end_reason <> 'already_matched')
`

type SeriesTotalsParams struct {
	WorkspaceID ids.UUID `json:"workspace_id"`
	SeriesID    ids.UUID `json:"series_id"`
}

type SeriesTotalsRow struct {
	Entered  int64 `json:"entered"`
	Active   int64 `json:"active"`
	Finished int64 `json:"finished"`
	Exited   int64 `json:"exited"`
	Goal     int64 `json:"goal"`
}

// SeriesTotals counts what happened to a series' travelers.
func (q *Queries) SeriesTotals(ctx context.Context, arg SeriesTotalsParams) (SeriesTotalsRow, error) {
	row := q.db.QueryRow(ctx, seriesTotals, arg.WorkspaceID, arg.SeriesID)
	var i SeriesTotalsRow
	err := row.Scan(
		&i.Entered,
		&i.Active,
		&i.Finished,
		&i.Exited,
		&i.Goal,
	)
	return i, err
}

const seriesVariantGoals = `-- name: SeriesVariantGoals :many
SELECT coalesce(variants ->> $1::text, '')::text AS path, count(*) AS entered,
    count(*) FILTER (WHERE goal_at IS NOT NULL) AS goal
FROM series_enrollments
WHERE workspace_id = $2 AND series_id = $3 AND NOT test AND variants ? $1::text
GROUP BY 1
`

