const setSeriesEnrollmentWait = `-- name: SetSeriesEnrollmentWait :exec
UPDATE series_enrollments SET wait = $1, updated_at = $2::timestamptz
WHERE workspace_id = $3 AND id = $4 AND seq = $5 AND status = 'waiting'
`

type SetSeriesEnrollmentWaitParams struct {
	Wait        json.RawMessage `json:"wait"`
	Now         time.Time       `json:"now"`
	WorkspaceID ids.UUID        `json:"workspace_id"`
	ID          ids.UUID        `json:"id"`
	Seq         int64           `json:"seq"`
}

// SetSeriesEnrollmentWait stores what a job outside the transaction
// learned for the step the enrollment waits on.
func (q *Queries) SetSeriesEnrollmentWait(ctx context.Context, arg SetSeriesEnrollmentWaitParams) error {
	_, err := q.db.Exec(ctx, setSeriesEnrollmentWait,
		arg.Wait,
		arg.Now,
		arg.WorkspaceID,
		arg.ID,
		arg.Seq,
	)
	return err
}
